insert into public.models (brand, model, category_id, sort)
select l.brand, l.model, (select id from public.categories where name = l.cat),
       coalesce((select max(sort) from public.models x where x.brand = l.brand and x.sort < 1000), 0) + l.n
from list l
where not exists (select 1 from public.models x where lower(x.brand) = lower(l.brand) and lower(x.model) = lower(l.model));

