update public.models m set category_id = (select id from public.categories where name = l.cat)
from list l
where lower(m.brand) = lower(l.brand) and lower(m.model) = lower(l.model) and m.category_id is null;

select c.name as category, count(*) as models from public.models m left join public.categories c on c.id = m.category_id group by 1 order by 1;
